// Page awareness for the dreamer: what he can stand on, and when something on
// the page is worth flying to. Pure DOM reading -- Dreamer.js decides how to
// get there.
//
// He deliberately does NOT react to what the visitor is reading (the old
// scroll-pause -> heading and card-hover -> card rules put him exactly where
// their eyes were). The one intent left:
//   cta -- the visitor reached the bottom of the page: land by the contact
//          call to action (once per page)
// and the director reports how long the visitor has been quiet, so Dreamer
// only moves while nobody is reading.

// Headroom he needs above a perch (he's ~105 px tall) and below the viewport
// top, so a perch never pushes his head off screen.
export const PERCH_MIN_TOP = 120;

const HEADINGS = "h1, h2, h3";
const CTA_TEXT = /get in touch|contact|hire me|email me|say hi|let'?s talk|work together/i;

const isCardEl = (el) =>
  el.tagName === "ARTICLE" ||
  Array.from(el.classList || []).some((c) => /card$/i.test(c));

const ignored = (el) => !!el.closest("[data-pet-ignore], [aria-hidden='true']");

// Fixed/sticky things (nav, chat bubbles) move with the viewport, not the
// page, so standing on them would look like floating.
const inFixedLayer = (el) => {
  for (let n = el, hops = 0; n && n !== document.body && hops < 8; hops += 1) {
    const pos = window.getComputedStyle(n).position;
    if (pos === "fixed" || pos === "sticky") return true;
    n = n.parentElement;
  }
  return false;
};

// The surface he'd stand on, in viewport px: {x1, x2, top}. Headings use the
// first line of actual text (a block <h1> is often far wider than its words).
export const perchRect = (el) => {
  if (!el || !el.isConnected) return null;
  let r;
  if (/^H[1-4]$/.test(el.tagName)) {
    try {
      const range = document.createRange();
      range.selectNodeContents(el);
      const rects = Array.from(range.getClientRects()).filter((x) => x.width > 4);
      if (rects.length) {
        const top = Math.min(...rects.map((x) => x.top));
        const line = rects.filter((x) => x.top < top + 4);
        // The glyph box starts at the font's ascent, well above the capitals
        // (~20% of the font size, plus any half-leading) -- stand on the
        // letters, not on the air above them.
        const fs = parseFloat(window.getComputedStyle(el).fontSize) || 16;
        const h = line[0].height;
        const capTop = top + Math.max(0, (h - fs) / 2) + fs * 0.2;
        r = {
          left: Math.min(...line.map((x) => x.left)),
          right: Math.max(...line.map((x) => x.right)),
          top: capTop,
        };
      }
    } catch (e) {
      r = null;
    }
  }
  if (!r) r = el.getBoundingClientRect();
  if (r.right - r.left < 60) return null;
  return { x1: r.left, x2: r.right, top: r.top };
};

export const perchFits = (rect, vh) =>
  !!rect && rect.top >= PERCH_MIN_TOP && rect.top <= vh - 30;

export const describe = (el) =>
  (el?.getAttribute?.("aria-label") || el?.textContent || "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 40);

const visibleCandidates = (selector, vh, filter) => {
  const out = [];
  let nodes;
  try {
    nodes = document.querySelectorAll(selector);
  } catch (e) {
    return out;
  }
  for (let i = 0; i < nodes.length && i < 400; i += 1) {
    const el = nodes[i];
    if (ignored(el) || (filter && !filter(el))) continue;
    const r = perchRect(el);
    if (!perchFits(r, vh)) continue;
    if (inFixedLayer(el)) continue;
    out.push({ el, r });
  }
  return out;
};

// Something to land on when he just fancies a rest: a heading or a card in
// view, or null for the floor.
export const pickRestingPerch = (vw, vh) => {
  const all = [
    ...visibleCandidates(HEADINGS, vh),
    ...visibleCandidates("article, [class*='card']", vh, (el) => {
      if (!isCardEl(el)) return false;
      const w = el.getBoundingClientRect().width;
      return w >= 160 && w <= vw * 0.8;
    }),
  ];
  if (!all.length) return null;
  const c = all[Math.floor(Math.random() * all.length)];
  return { el: c.el, reason: "rest" };
};

const findCta = (vh) => {
  const els = visibleCandidates("a, button", vh, (el) =>
    CTA_TEXT.test(el.textContent || el.getAttribute("aria-label") || "")
  );
  if (!els.length) return null;
  // Prefer a real CTA block over, say, a nav link that happens to say
  // "Contact".
  const inCta = els.find((c) => c.el.closest("[class*='cta'], footer, section"));
  return (inCta || els[0]).el;
};

export const createDirector = ({ onIntent }) => {
  let lastScrollAt = 0;
  // Anything the visitor does -- scrolling, moving the pointer, typing --
  // means they're reading or working; he holds still until they stop.
  let lastActiveAt = Date.now();
  let ctaDoneFor = null;

  const onScroll = () => {
    lastScrollAt = Date.now();
    lastActiveAt = lastScrollAt;
  };
  const onActive = () => {
    lastActiveAt = Date.now();
  };

  const tick = () => {
    const now = Date.now();
    const vh = window.innerHeight;
    const path = window.location.pathname;
    const doc = document.documentElement;

    // Bottom of the page -> the contact CTA, once per page.
    const atBottom = window.scrollY + vh >= doc.scrollHeight - 80;
    if (atBottom && ctaDoneFor !== path && now - lastScrollAt > 1500) {
      const cta = findCta(vh);
      if (cta) {
        ctaDoneFor = path;
        onIntent({ el: cta, reason: "cta" });
      }
    }
  };

  window.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("wheel", onActive, { passive: true });
  window.addEventListener("pointermove", onActive, { passive: true });
  window.addEventListener("keydown", onActive, { passive: true });
  const timer = setInterval(tick, 400);

  return {
    // ms since the visitor last did anything
    quietFor: () => Date.now() - lastActiveAt,
    // ms since the visitor last scrolled (Infinity if they never have)
    sinceScroll: () => (lastScrollAt ? Date.now() - lastScrollAt : Infinity),
    destroy: () => {
      clearInterval(timer);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("wheel", onActive);
      window.removeEventListener("pointermove", onActive);
      window.removeEventListener("keydown", onActive);
    },
  };
};
