// The dreamer: a small person who walks, breaks into a run, starts flapping
// his arms like wings, and -- slowly, the way it happens in dreams -- lifts off
// and flies around the screen before gliding back down.
//
// One transparent, click-through canvas covers the viewport. The camera is
// orthographic with 1 world unit = 1 CSS px (y up from the bottom edge), so
// the flight controller below can think purely in screen pixels.
import React, {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
} from "react";
import * as THREE from "three";
import {
  PALETTE,
  applyPose,
  buildRig,
  flapArms,
  flarePose,
  carryArms,
  dashArms,
  flyBody,
  groundPose,
  mixInto,
} from "./DreamerRig";
import {
  createDirector,
  describe,
  perchFits,
  perchRect,
  pickRestingPerch,
} from "./DreamerDirector";
import { companions, emit as emitWorld, fresh, on as onWorld } from "../companionBus";

// Mochi's sprite is ~78 px tall; her scruff sits about this far above her feet.
const PET_SCRUFF = 62;

// Per-tab memory so a reload (or a hard navigation) doesn't reset him mid-air.
const SAVE_KEY = "dreamer:state";
const SAVE_MAX_AGE_MS = 30 * 60 * 1000;

// On the real site ("site" pace) he's a cameo, not a resident: he flies on
// his own once per session, then stays on the floor. The flight comes after
// the visitor has spent a while on the home page, or when they reach the
// contact CTA at the bottom of a page.
const CAMEO_KEY = "dreamer:cameo";
const CAMEO_PATHS = ["/", "/home"];
const CAMEO_AFTER_MS = 25000;
// He only moves (walks, takes off) once the visitor has been still this long.
const QUIET_MS = 8000;

const PX = 58; // px per metre -> ~105 px tall
const GROUND = 14; // feet line, px above the bottom edge
const G = 1100; // gravity, px/s^2
const WALK = 52;
const RUN = 170;
const CRUISE = 150;
const TRAIL_N = 44;
const MIN_V = 70;
const MAX_V = 360;
const MIN_TURN_R = 85; // px: the tightest arc he can carve
const LOOP_R = 80;
const DIVE_G = 240; // how hard gravity trades height for speed
// How far the chest turns toward the camera in level flight, so we see his
// face and the spread of his arms rather than a flat side-on silhouette.
const ROLL_VIEW = 0.55;
const TAU = Math.PI * 2;
const wrap = (a) => Math.atan2(Math.sin(a), Math.cos(a));

// Body orientation for flight: head along the heading `th`, chest (+z of the
// rig) rolled by `roll` about that axis -- 0 is belly-down when heading right,
// PI belly-down when heading left, PI/2 chest to the camera.
const _X = new THREE.Vector3();
const _Y = new THREE.Vector3();
const _Z = new THREE.Vector3();
const _M = new THREE.Matrix4();
const flightQuat = (th, roll, out) => {
  const c = Math.cos(th);
  const sn = Math.sin(th);
  _Y.set(c, sn, 0);
  _Z.set(sn * Math.cos(roll), -c * Math.cos(roll), Math.sin(roll)).normalize();
  _X.crossVectors(_Y, _Z);
  _M.makeBasis(_X, _Y, _Z);
  return out.setFromRotationMatrix(_M);
};

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const rand = (lo, hi) => lo + Math.random() * (hi - lo);
// Frame-rate independent exponential approach.
const ease = (cur, target, rate, dt) =>
  cur + (target - cur) * (1 - Math.exp(-rate * dt));

const Dreamer = forwardRef(function Dreamer(
  {
    isLight = true,
    autopilot = true,
    zIndex = 60,
    onModeChange,
    // "lab" is restless for tuning; "site" rests longer between flights so a
    // visitor reading the page isn't constantly distracted.
    pace = "lab",
    paused = false,
    // React to the page (land on the heading you stop at, the card you
    // hover, the contact CTA at the bottom) instead of only wandering.
    pageAware = true,
    // Analytics hook: onEvent(type, label). Types: "seen", "click", "perch".
    onEvent,
  },
  ref
) {
  const hostRef = useRef(null);
  const ctl = useRef({ autopilot, follow: false, cmd: null });
  const modeCb = useRef(onModeChange);
  modeCb.current = onModeChange;
  const eventCb = useRef(onEvent);
  eventCb.current = onEvent;
  ctl.current.autopilot = autopilot;
  ctl.current.paused = paused;
  const calm = pace === "site";

  useImperativeHandle(ref, () => ({
    takeOff: () => (ctl.current.cmd = "takeoff"),
    land: () => (ctl.current.cmd = "land"),
    walk: () => (ctl.current.cmd = "walk"),
    scoop: () => (ctl.current.cmd = "scoop"),
    setFollow: (on) => (ctl.current.follow = !!on),
  }));

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return undefined;
    const pal = isLight ? PALETTE.light : PALETTE.dark;

    let vw = window.innerWidth;
    let vh = window.innerHeight;

    const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
    // A full-viewport canvas: cap the pixel ratio on real pages to keep the
    // fill cost down; the figure is small enough that 1.5x still looks crisp.
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, calm ? 1.5 : 2));
    renderer.setSize(vw, vh);
    renderer.outputEncoding = THREE.sRGBEncoding;
    host.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const camera = new THREE.OrthographicCamera(0, vw, vh, 0, 1, 4000);
    camera.position.z = 2000;

    scene.add(new THREE.HemisphereLight("#ffffff", "#8a7f9a", 0.95));
    const key = new THREE.DirectionalLight("#fff4e6", 0.9);
    key.position.set(-0.6, 1, 1.2);
    scene.add(key);
    const rim = new THREE.DirectionalLight("#c7d2fe", 0.45);
    rim.position.set(1, 0.4, -1);
    scene.add(rim);

    const rig = buildRig(pal);
    rig.root.scale.setScalar(PX);
    // Look down on him a little, so a spread wingspan reads as width instead
    // of collapsing into the side-on silhouette.
    rig.root.rotation.x = 0.32;
    scene.add(rig.root);

    const shadow = new THREE.Mesh(
      new THREE.CircleGeometry(1, 32),
      new THREE.MeshBasicMaterial({
        color: pal.shadow,
        transparent: true,
        opacity: 0.16,
        depthWrite: false,
      })
    );
    shadow.position.z = -300;
    scene.add(shadow);

    // A faint streak of air behind each hand while he flies.
    const makeTrail = () => {
      const geo = new THREE.BufferGeometry();
      const pos = new Float32Array(TRAIL_N * 3);
      const col = new Float32Array(TRAIL_N * 4);
      const c = new THREE.Color(pal.trail).convertSRGBToLinear();
      for (let i = 0; i < TRAIL_N; i += 1) {
        col[i * 4] = c.r;
        col[i * 4 + 1] = c.g;
        col[i * 4 + 2] = c.b;
      }
      geo.setAttribute("position", new THREE.BufferAttribute(pos, 3));
      geo.setAttribute("color", new THREE.BufferAttribute(col, 4));
      const line = new THREE.Line(
        geo,
        new THREE.LineBasicMaterial({
          vertexColors: true,
          transparent: true,
          depthWrite: false,
        })
      );
      line.frustumCulled = false;
      scene.add(line);
      return { line, pos, col, primed: false };
    };
    const trails = [makeTrail(), makeTrail()];
    const handPos = new THREE.Vector3();
    const qUp = new THREE.Quaternion();
    const qFly = new THREE.Quaternion();
    const _E = new THREE.Euler();

    const s = {
      mode: "idle",
      timer: calm ? rand(3, 6) : 1.5,
      t: 0,
      x: calm ? rand(vw * 0.15, vw * 0.6) : vw * 0.25,
      y: GROUND,
      vx: 0,
      vy: 0,
      dir: 1,
      yaw: 0.9,
      phase: 0,
      psi: 0,
      flapA: 0,
      flapF: 1,
      wFly: 0,
      wArms: 0,
      wFlare: 0,
      wTrail: 0,
      dip: 0,
      look: 0,
      lookTarget: 0,
      lookTimer: 2,
      blinkIn: 2.5,
      tt: 0,
      flightT: 0,
      flightDur: 16,
      soarT: 0,
      wp: null,
      wpT: 0,
      landX: 0,
      mouse: null,
      // Flight: heading (rad, 0 = right, CCW), speed (px/s), turn rate.
      th: 0,
      v: 0,
      om: 0,
      belly: 1, // +1 belly-down heading right, -1 heading left
      roll: ROLL_VIEW,
      man: null, // active manoeuvre, e.g. a loop
      cruise: CRUISE,
      flaring: false,
      wHover: 0,
      wDash: 0,
      flapNeed: 0,
      // Where he stands: null = the floor line, else {el, reason} -- a
      // heading, card or button he landed on, followed as the page scrolls.
      perch: null,
      goal: null, // the perch he's flying to
      jumped: false,
      seen: false,
      saveIn: 1,
      // Playing with Mochi: the scoop manoeuvre and where his hands are.
      scoop: null, // {phase: "approach" | "grab" | "carry" | "drop", t, wp}
      wantScoop: false,
      nextScoopAt: performance.now() + (calm ? 25000 : 4000),
      wCarry: 0,
      cp: { x: 0, y: 0 }, // carry point, screen px
      path: window.location.pathname,
      pathAt: performance.now(),
      fullFlight: false,
    };

    let cameoUsed = false;
    try {
      cameoUsed = window.sessionStorage.getItem(CAMEO_KEY) === "1";
    } catch (e) {
      /* storage blocked: one cameo per page load instead */
    }
    const spendCameo = () => {
      cameoUsed = true;
      try {
        window.sessionStorage.setItem(CAMEO_KEY, "1");
      } catch (e) {
        /* ignore */
      }
    };
    const cameoDue = () =>
      !cameoUsed &&
      CAMEO_PATHS.includes(s.path) &&
      performance.now() - s.pathAt > CAMEO_AFTER_MS;

    const emit = (type, label = "") => {
      if (eventCb.current) eventCb.current(type, label);
    };

    // The surface under him right now: {y (world px), x1, x2}, or null if his
    // perch has scrolled out of reach or left the page.
    const surface = () => {
      if (!s.perch) return { y: GROUND, x1: 50, x2: vw - 50 };
      const r = perchRect(s.perch.el);
      if (!perchFits(r, vh)) return null;
      return { y: vh - r.top, x1: r.x1 + 22, x2: r.x2 - 22 };
    };

    // Restore a flight that was in progress before a reload.
    if (calm) {
      try {
        const saved = JSON.parse(window.sessionStorage.getItem(SAVE_KEY) || "null");
        if (saved && Date.now() - saved.at < SAVE_MAX_AGE_MS) {
          s.x = clamp(saved.fx * vw, 60, vw - 60);
          if (saved.air) {
            s.y = clamp(saved.fy * vh, GROUND + 90, vh - 90);
            s.th = saved.th || 0;
            s.v = clamp(saved.v || CRUISE, MIN_V, MAX_V);
            s.belly = Math.cos(s.th) >= 0 ? 1 : -1;
            s.roll = s.belly > 0 ? ROLL_VIEW : Math.PI - ROLL_VIEW;
            s.dir = s.belly;
            s.wFly = 1;
            s.wArms = 1;
            s.mode = "fly";
            s.flightDur = rand(2, 4);
            s.seen = true;
          } else {
            s.timer = rand(2, 5);
          }
        }
      } catch (e) {
        /* storage blocked: start fresh */
      }
    }
    const save = () => {
      if (!calm) return;
      try {
        window.sessionStorage.setItem(
          SAVE_KEY,
          JSON.stringify({
            at: Date.now(),
            fx: s.x / vw,
            fy: s.y / vh,
            air: s.mode !== "idle" && s.mode !== "walk" ? true : !!s.perch,
            th: s.th,
            v: s.v,
          })
        );
      } catch (e) {
        /* ignore */
      }
    };

    const setMode = (m, timer = 0) => {
      s.mode = m;
      s.timer = timer;
      s.tt = 0;
      if (modeCb.current) modeCb.current(m);
    };

    const pickWaypoint = () => {
      // On the site he keeps to the band below the reading line.
      const top = calm ? Math.max(GROUND + 170, vh * 0.36) : vh - 90;
      const bottom = calm ? GROUND + 90 : Math.min(top - 40, GROUND + vh * 0.28);
      // Prefer a point a good distance away and roughly ahead, so flights
      // sweep in long arcs instead of doubling back every few seconds.
      let best = null;
      for (let i = 0; i < 6; i += 1) {
        const c = { x: rand(90, vw - 90), y: rand(bottom, top) };
        const d = Math.hypot(c.x - s.x, c.y - s.y);
        const ahead = Math.cos(Math.atan2(c.y - s.y, c.x - s.x) - s.th);
        const score = -Math.abs(d - 480) + 220 * ahead;
        if (!best || score > best.score) best = { ...c, d, score };
      }
      s.wp = best;
      s.wpT = 0;
      // Long legs are sometimes a dash: fist forward, full speed.
      s.cruise = !calm && best.d > 520 && Math.random() < 0.45 ? 330 : CRUISE;
      // And now and then a loop, when there's room for one.
      const room =
        s.y > GROUND + 140 &&
        s.y + 2 * LOOP_R + 90 < vh &&
        s.x > 140 &&
        s.x < vw - 140 &&
        Math.abs(Math.cos(s.th)) > 0.75;
      if (!calm && !s.man && room && Math.random() < 0.3)
        s.man = { sign: s.belly, turned: 0 };
    };

    // Momentum flight: the heading turns at a limited, eased rate (so every
    // path is an arc), and speed trades with height -- dives accelerate,
    // climbs bleed speed unless he beats his arms.
    const glide = (tx, ty, dt, cruise, floor, landing = false) => {
      const d = Math.hypot(tx - s.x, ty - s.y) || 1;
      let want = Math.atan2(ty - s.y, tx - s.x);
      want += 0.22 * Math.sin(s.t * 0.6) * clamp(d / 300, 0, 1); // lazy weave
      // Look ahead and bend away from the screen edges before reaching them.
      const la = 0.9 * s.v + 60;
      const lx = s.x + Math.cos(s.th) * la;
      const ly = s.y + Math.sin(s.th) * la;
      // Coming in to land, ground ahead means flare, not pull away.
      s.floorAhead = ly < floor;
      const urgent =
        lx < 60 || lx > vw - 60 || ly > vh - 60 || (s.floorAhead && !landing);
      if (urgent) want = Math.atan2(vh * (calm ? 0.22 : 0.55) - s.y, vw / 2 - s.x);
      let diff = wrap(want - s.th);
      // Reversing course: go over the top when there's headroom (a half loop
      // and roll-out), otherwise swoop under.
      if (Math.abs(diff) > 2.3 && !urgent) {
        // (Coming in to land he always swoops under.)
        const over = !calm && !landing && s.y < vh - 250 ? 1 : -1;
        diff = over * s.belly * Math.abs(diff);
      }
      // Tight arcs when slow, broad sweeping ones at speed.
      const omMax = Math.min(s.v / MIN_TURN_R, 2.3);
      let omT = clamp(diff * (urgent ? 3 : 1.7), -omMax, omMax);
      if (s.man) {
        omT = (s.man.sign * s.v) / LOOP_R;
        s.man.turned += Math.abs(s.om) * dt;
        if (s.man.turned > TAU - 0.2) s.man = null;
      }
      s.om = ease(s.om, omT, 3.2, dt);
      s.th = wrap(s.th + s.om * dt);

      const climb = Math.sin(s.th);
      const need =
        clamp(0.2 + 1.1 * Math.max(0, climb) + (170 - s.v) / 90, 0, 1) *
        (1 - s.wDash);
      // Each downbeat is a visible surge.
      const pulse = 1 + 0.9 * Math.max(0, -Math.cos(s.psi));
      s.v +=
        (-DIVE_G * climb + 0.8 * (cruise - s.v) + 150 * need * pulse) * dt;
      s.v = clamp(s.v, MIN_V, MAX_V);
      s.vx = Math.cos(s.th) * s.v;
      s.vy = Math.sin(s.th) * s.v;
      return need;
    };

    // Iron-Man hover: a critically damped spring onto the target.
    const hoverTo = (tx, ty, dt) => {
      const k = 7;
      const c = 2 * Math.sqrt(k) * 0.95;
      s.vx += ((tx - s.x) * k - s.vx * c) * dt;
      s.vy += ((ty - s.y) * k - s.vy * c) * dt;
      s.v = Math.max(MIN_V, Math.hypot(s.vx, s.vy));
      if (Math.hypot(s.vx, s.vy) > 50) s.th = Math.atan2(s.vy, s.vx);
      s.om = ease(s.om, 0, 4, dt);
    };

    const startTakeoff = () => {
      // From a perch there's no room for the dreamy run-up: hop off instead.
      if (s.perch) return startLaunch();
      // Run toward the side with more room.
      s.dir = s.x < vw / 2 ? 1 : -1;
      setMode("takeoff");
      return undefined;
    };

    // Quick takeoff: crouch, spring up with a burst of wingbeats. Used from
    // perches and when reacting to the page, where the run-up would be slow.
    const startLaunch = () => {
      s.jumped = false;
      if (s.x < 140) s.dir = 1;
      else if (s.x > vw - 140) s.dir = -1;
      setMode("launch");
    };

    const enterFlight = () => {
      s.th = Math.atan2(s.vy, s.vx);
      s.v = Math.max(140, Math.hypot(s.vx, s.vy));
      s.om = 0;
      s.flightT = 0;
      // On the site only the cameo (or a flight the visitor asked for by
      // clicking him) is a real flight; anything else, e.g. springing off a
      // perch that scrolled away, is a short glide back down to the floor.
      s.flightDur = !calm ? rand(14, 22) : s.fullFlight ? rand(8, 12) : rand(1.5, 2.5);
      s.fullFlight = false;
      if (!s.seen) {
        s.seen = true;
        emit("seen", window.location.pathname);
      }
      if (s.goal && !s.wantScoop) return startLanding();
      pickWaypoint();
      setMode("fly");
      if (s.wantScoop) {
        s.wantScoop = false;
        startScoop();
      }
      return undefined;
    };

    const startLanding = () => {
      if (s.scoop) endScoop(true);
      // Half the unprompted landings pick something on the page to sit on.
      if (!calm && !s.goal && pageAware && ctl.current.autopilot && Math.random() < 0.5)
        s.goal = pickRestingPerch(vw, vh);
      const r = s.goal && perchRect(s.goal.el);
      if (s.goal && perchFits(r, vh)) {
        // The nearest spot on it that leaves room for his feet.
        s.landX =
          r.x2 - r.x1 < 70 ? (r.x1 + r.x2) / 2 : clamp(s.x, r.x1 + 30, r.x2 - 30);
      } else {
        s.goal = null;
        // Land ahead of him, unless that runs into a screen edge -- then
        // behind, toward open space.
        const ahead = Math.sign(Math.cos(s.th) || s.dir);
        let lx = s.x + ahead * rand(220, 380);
        if (lx < vw * 0.12 || lx > vw * 0.88) lx = s.x - ahead * rand(220, 380);
        s.landX = clamp(lx, 90, vw - 90);
      }
      s.man = null;
      s.flaring = false;
      setMode("land");
    };

    const petNow = () => (fresh(companions.pet) ? companions.pet : null);

    const startScoop = () => {
      s.scoop = { phase: "approach", t: 0, wp: null };
      s.goal = null;
      s.man = null;
      emit("scoop", window.location.pathname);
    };

    // Let go of her (or give up the attempt) and carry on flying.
    const endScoop = (release) => {
      const c = companions.carry;
      if (c && c.state === "held") {
        if (release) {
          c.state = "released";
          c.vx = s.vx;
          c.vy = -s.vy * 0.4; // screen y is down
        } else c.state = "released";
      } else if (c && (c.state === "requested" || c.state === "cancelled")) {
        companions.carry = null;
      }
      s.scoop = null;
      s.nextScoopAt = performance.now() + (calm ? 90000 : 15000);
      s.flightDur = Math.max(s.flightDur, s.flightT + rand(3, 6));
    };

    const nextOnGround = () => {
      if (calm) {
        // The site: one cameo flight per session, otherwise he mostly stands
        // and now and then takes a few steps. On a perch (the contact CTA) he
        // stays put until it scrolls away.
        if (!s.perch && cameoDue()) {
          spendCameo();
          s.fullFlight = true;
          startTakeoff();
        } else if (s.mode === "idle" && !s.perch && Math.random() < 0.5) {
          s.dir = s.x < 120 ? 1 : s.x > vw - 120 ? -1 : Math.random() < 0.5 ? -1 : 1;
          setMode("walk", rand(1.5, 3));
        } else setMode("idle", rand(8, 16));
        return;
      }
      if (s.perch) {
        const surf = surface();
        const roomy = surf && surf.x2 - surf.x1 > 120;
        const r = Math.random();
        if (roomy && s.mode === "idle" && r < 0.35) {
          s.dir = Math.random() < 0.5 ? -1 : 1;
          setMode("walk", rand(1.5, 3));
        } else if (r < (calm ? 0.6 : 0.75)) startLaunch();
        else setMode("idle", calm ? rand(6, 12) : rand(2, 4));
        return;
      }
      if (s.mode === "idle") {
        s.dir = s.x < 120 ? 1 : s.x > vw - 120 ? -1 : Math.random() < 0.5 ? -1 : 1;
        setMode("walk", rand(2.5, 4.5));
      } else if (Math.random() < (calm ? 0.4 : 0.65)) startTakeoff();
      else setMode("idle", calm ? rand(5, 11) : rand(1.8, 3.5));
    };

    const onPointerMove = (e) => {
      s.mouse = { x: e.clientX, y: vh - e.clientY };
    };
    // The canvas is click-through, so hit-test the body from the window.
    const onPointerDown = (e) => {
      const cx = s.x;
      const cy = vh - (s.y + 0.9 * PX);
      if (Math.abs(e.clientX - cx) > 60 || Math.abs(e.clientY - cy) > 70) return;
      // A click meant for the page underneath is not a click on him.
      if (
        e.target &&
        e.target.closest &&
        e.target.closest("a, button, input, textarea, select, label, [role='button']")
      )
        return;
      ctl.current.cmd = s.mode === "fly" ? "land" : "takeoff";
      if (ctl.current.cmd === "takeoff") s.fullFlight = true;
      emit("click", s.mode);
    };
    const onResize = () => {
      vw = window.innerWidth;
      vh = window.innerHeight;
      renderer.setSize(vw, vh);
      camera.right = vw;
      camera.top = vh;
      camera.updateProjectionMatrix();
      s.x = clamp(s.x, 40, vw - 40);
      s.y = clamp(s.y, GROUND, vh - 60);
    };
    window.addEventListener("pointermove", onPointerMove, { passive: true });
    window.addEventListener("pointerdown", onPointerDown, { passive: true });
    window.addEventListener("resize", onResize);
    window.addEventListener("pagehide", save);
    const director = pageAware
      ? createDirector({ onIntent: (intent) => (ctl.current.intent = intent) })
      : null;

    const step = (dt) => {
      s.t += dt;
      s.tt += dt;
      if (window.location.pathname !== s.path) {
        s.path = window.location.pathname;
        s.pathAt = performance.now();
      }
      const alt = s.y - GROUND;
      const grounded = s.mode === "idle" || s.mode === "walk";

      // Commands from the page / clicks.
      const cmd = ctl.current.cmd;
      ctl.current.cmd = null;
      if (cmd === "takeoff" && grounded) startTakeoff();
      else if (cmd === "land" && s.mode === "launch") s.goal = null;
      else if (cmd === "land" && (s.mode === "fly" || s.mode === "takeoff"))
        startLanding();
      else if (cmd === "walk" && grounded) setMode("walk", rand(3, 5));
      else if (cmd === "scoop" && !s.scoop) {
        if (s.mode === "fly") startScoop();
        else {
          s.wantScoop = true;
          if (grounded) startLaunch();
        }
      }

      // Page reactions (see DreamerDirector): fly to what the visitor is
      // looking at. Ignored while he's following the cursor.
      const intent = ctl.current.intent;
      ctl.current.intent = null;
      if (
        intent &&
        ctl.current.autopilot &&
        !ctl.current.follow &&
        !(s.perch && s.perch.el === intent.el) &&
        !(calm && cameoUsed)
      ) {
        if (calm) spendCameo();
        s.goal = intent;
        if (grounded) startLaunch();
        else if (s.mode === "fly" || s.mode === "land") startLanding();
        // takeoff / launch pick the goal up when they hand over to flight.
      }

      let wFly = 0;
      let wArms = 0;
      let wFlare = 0;
      let flapA = 0;
      let flapF = 1;
      let climb = 0;
      let wHover = 0;

      if (s.mode === "idle" || s.mode === "walk") {
        const surf = surface();
        if (!surf) {
          // His perch scrolled away (or the route changed): spring off into
          // the air from where he is -- no crouch, there's nothing under him.
          s.perch = null;
          startLaunch();
          s.tt = 0.22;
        } else {
          const target = s.mode === "walk" ? s.dir * WALK : 0;
          s.vx = ease(s.vx, target, s.mode === "walk" ? 2.5 : 4, dt);
          if (s.mode === "walk") {
            if (s.x < surf.x1) s.dir = 1;
            if (s.x > surf.x2) s.dir = -1;
          }
          // Someone is reading: stop and stand still until they've been
          // quiet for a while.
          const hush = calm && director && director.quietFor() < QUIET_MS;
          if (hush && s.mode === "walk" && ctl.current.autopilot)
            setMode("idle", rand(2, 4));
          if (!hush) s.timer -= dt;
          if (s.timer <= 0 && ctl.current.autopilot) nextOnGround();
          else if (s.timer <= 0 && s.mode === "walk") setMode("idle", 1e9);
        }
      } else if (s.mode === "launch") {
        const tt = s.tt;
        wArms = clamp(tt / 0.25, 0, 1);
        flapA = 0.85;
        flapF = 1.6;
        if (tt < 0.22) {
          // Crouch, still standing on whatever he's on.
          s.vx = ease(s.vx, 0, 6, dt);
          s.vy = 0;
          s.dip = Math.max(s.dip, 0.08 * (tt / 0.22));
          const surf = surface();
          if (surf && (s.perch || s.y <= GROUND + 1)) s.y = surf.y;
        } else {
          if (!s.jumped) {
            s.jumped = true;
            s.perch = null;
            s.vy = 270;
            s.vx = s.dir * 110;
          }
          s.vy -= 260 * dt;
        }
        wFly = clamp((tt - 0.22) / 0.5, 0, 1);
        climb = clamp(s.vy / 160, -1, 1);
        if (tt > 0.75) enterFlight();
      } else if (s.mode === "takeoff") {
        // Walk -> run -> flap while running -> hops -> finally airborne.
        // Beats: walk (0-1.2s), run (1.2s+), arms start (1.6s+), heavy
        // hops that grow until the ground lets go (~4-5s).
        const tt = s.tt;
        const runUp = tt < 1.2 ? 0 : clamp((tt - 1.2) / 1.4, 0, 1);
        s.vx = ease(s.vx, s.dir * (WALK + (RUN - WALK) * runUp), 2.2, dt);
        if (alt < 2 && (s.x < 40 || s.x > vw - 40)) s.dir = s.x < 40 ? 1 : -1;
        wArms = clamp((tt - 1.6) / 0.8, 0, 1);
        flapA = 0.3 + 0.55 * clamp((tt - 1.6) / 1.6, 0, 1);
        flapF = 1.0;
        const k = clamp((tt - 2.4) / 3.2, 0, 1.2);
        const down = Math.max(0, -Math.cos(s.psi));
        const lift = G * k * 1.15 * (1 + 0.9 * down) * wArms;
        s.vy += (lift - G) * dt;
        // Dreams are slow: the climb floats rather than launches.
        s.vy = Math.min(s.vy, 55 + 45 * k);
        if (alt > 1 && Math.abs(s.x - vw / 2) > vw / 2 - 60) s.vx *= 1 - dt * 2;
        wFly = clamp(alt / 110, 0, 1) * 0.85;
        climb = clamp(s.vy / 160, -1, 1);
        if (alt > 110) enterFlight();
      } else if (s.mode === "fly" && s.scoop) {
        // ---- scoop Mochi up for a short flight ----
        const sc = s.scoop;
        sc.t += dt;
        s.flightT += dt;
        const pet = petNow();
        const c = companions.carry;
        let tx = s.x;
        let ty = s.y;
        if (sc.phase === "approach") {
          if (!pet || !pet.free || !pet.onFloor || sc.t > 8) endScoop(false);
          else {
            // Swoop so his hands pass right over her scruff: aim his body at
            // the height that puts the carry point level with it.
            const scruffY = pet.y - PET_SCRUFF;
            // Hands pass a little above her scruff (grab reach is 55 px), so
            // she's lifted up into them rather than him skimming the floor.
            const grabY = Math.max(GROUND + 30, s.y + (s.cp.y - scruffY) + 35);
            // Two stages: get down to her height off to one side, then a
            // level run-in -- a steep dive would bottom out after the grab.
            const side = pet.x >= s.x ? 1 : -1;
            const far = Math.abs(pet.x - s.x) > 170;
            tx = far ? pet.x - side * 150 : pet.x + side * 60;
            ty = far ? grabY + 60 : grabY;
            s.v = Math.min(s.v, 190);
            // Final run-in: a glide slope rather than heading steering --
            // level speed toward her, sink rate set to arrive at grab height.
            sc.runIn = !far;
            if (sc.runIn) {
              s.vx = ease(s.vx, side * 175, 3, dt);
              s.vy = ease(s.vy, clamp((grabY - s.y) * 2.8, -130, 110), 5, dt);
              s.th = Math.atan2(s.vy, s.vx);
              s.v = Math.hypot(s.vx, s.vy);
              s.om = 0;
            }
            // Only grab from a roughly level pass: pulling out of a steep dive
            // with her aboard would drag them both along the floor.
            if (
              Math.hypot(s.cp.x - pet.x, s.cp.y - scruffY) < 55 &&
              Math.sin(s.th) > -0.6
            ) {
              companions.carry = { state: "requested", x: s.cp.x, y: s.cp.y, vx: 0, vy: 0 };
              sc.phase = "grab";
              sc.t = 0;
            }
          }
        } else if (sc.phase === "grab") {
          tx = s.x + s.dir * 200;
          ty = GROUND + 120;
          if (c && c.state === "held") {
            sc.runIn = false;
            sc.phase = "carry";
            sc.t = 0;
            sc.wp = {
              x: clamp(s.x + s.dir * rand(300, 480), 120, vw - 120),
              y: GROUND + rand(230, 340),
            };
          } else if (!c || sc.t > 0.3) endScoop(false);
        } else if (sc.phase === "carry" || sc.phase === "drop") {
          if (!c || c.state !== "held") endScoop(false);
          else if (sc.phase === "carry") {
            tx = sc.wp.x;
            ty = sc.wp.y;
            if (Math.hypot(tx - s.x, ty - s.y) < 90)
              sc.wp = {
                x: clamp(s.x + s.dir * rand(260, 420), 120, vw - 120),
                y: GROUND + rand(200, 320),
              };
            if (sc.t > 4.5) {
              sc.phase = "drop";
              sc.t = 0;
            }
          } else {
            // Bring her back down and let go just above the ground.
            tx = s.x + s.dir * 220;
            ty = GROUND + 60;
            if (s.y - GROUND < 130 || sc.t > 3) endScoop(true);
          }
        }
        if (s.scoop && s.scoop.runIn && s.scoop.phase === "approach") {
          flapA = 0.12;
          flapF = 0.5; // gliding in, wings steady
        } else if (s.scoop) {
          // Low swoop on the way in; once she's aboard, the floor counts as
          // an edge again so he pulls up instead of skimming it.
          const inbound = sc.phase === "approach" || sc.phase === "drop";
          s.flapNeed = glide(
            tx,
            ty,
            dt,
            145,
            inbound ? GROUND + 2 : GROUND + 70,
            inbound
          );
          flapA = 0.12 + 0.55 * s.flapNeed;
          flapF = 0.5 + 0.85 * s.flapNeed;
          // Ground cushion for this deliberately low swoop: sink rate can't
          // exceed 3x the height above a 20 px clearance, so he eases in over
          // the floor instead of overshooting into it.
          const clear = Math.max(0, s.y - GROUND - 20);
          if (s.vy < -clear * 3) {
            s.vy = -clear * 3;
            s.th = Math.atan2(s.vy, s.vx);
            s.v = Math.max(MIN_V, Math.hypot(s.vx, s.vy));
          }
        }
        wFly = 1;
        wArms = 1;
        climb = Math.sin(s.th);
      } else if (s.mode === "fly") {
        s.flightT += dt;
        s.wpT += dt;
        const follow = ctl.current.follow && s.mouse;
        // Now and then, swoop down and pick Mochi up.
        const petFree = petNow();
        if (
          !follow &&
          !s.man &&
          !s.goal &&
          ctl.current.autopilot &&
          s.flightT > 2 &&
          performance.now() > s.nextScoopAt &&
          petFree &&
          petFree.free &&
          petFree.onFloor &&
          Math.abs(petFree.x - s.x) < 800 &&
          Math.random() < dt * 0.15
        )
          startScoop();
        let tx;
        let ty;
        if (follow) {
          // Hover beside the cursor (on the side he's on), not on top of it.
          tx = s.mouse.x + (s.x < s.mouse.x ? -95 : 95);
          ty = clamp(s.mouse.y - 85, GROUND + 90, vh - 80);
          s.cruise = CRUISE;
        } else {
          if (!s.wp || s.wpT > 8 || Math.hypot(s.wp.x - s.x, s.wp.y - s.y) < 90)
            pickWaypoint();
          tx = s.wp.x;
          ty = s.wp.y;
        }
        const hovering =
          follow && !s.man && Math.hypot(tx - s.x, ty - s.y) < (s.wHover > 0.5 ? 170 : 120);
        if (hovering) {
          hoverTo(tx, ty, dt);
          s.flapNeed = 0.45;
        } else {
          s.flapNeed = glide(tx, ty, dt, s.cruise, GROUND + 70);
        }
        wHover = hovering ? 1 : 0;
        wFly = 1;
        wArms = 1;
        flapA = hovering ? 0.32 : 0.1 + 0.55 * s.flapNeed;
        flapF = hovering ? 1.1 : 0.45 + 0.85 * s.flapNeed;
        climb = Math.sin(s.th);
        const scrolling = calm && director && director.sinceScroll() < 400;
        if (
          (s.flightT > s.flightDur || (scrolling && s.flightT > 1.5)) &&
          ctl.current.autopilot &&
          !ctl.current.follow &&
          !s.man
        )
          startLanding();
      } else if (s.mode === "land") {
        // Swoop in on a long arc, then flare upright and settle -- on the
        // floor, or on the page element he's heading for (which may be
        // moving if the visitor scrolls).
        let tx = s.landX;
        let ty = GROUND;
        if (s.goal) {
          const r = perchRect(s.goal.el);
          if (perchFits(r, vh)) {
            ty = vh - r.top;
            tx = clamp(s.landX, r.x1 + 20, r.x2 - 20);
            if (r.x2 - r.x1 < 60) tx = (r.x1 + r.x2) / 2;
          } else {
            s.goal = null; // gone from view: come down on the floor instead
          }
        }
        const altT = s.y - ty;
        // Approach from a little above the spot (kept inside the screen).
        const ay = Math.min(ty + 80, vh - 90);
        const d = Math.hypot(tx - s.x, ay - s.y);
        // Flare only from at or above the spot: coming up from below (e.g.
        // launching off the floor toward a heading) he flies to the approach
        // point first.
        if (
          !s.flaring &&
          altT > -5 &&
          (d < 110 ||
            altT < 60 ||
            (altT < 170 && Math.abs(tx - s.x) < 200) ||
            (s.floorAhead && altT < 260))
        )
          s.flaring = true;
        if (!s.flaring) {
          s.flapNeed = glide(tx, ay, dt, 125, ty + 20, true);
          flapA = 0.1 + 0.5 * s.flapNeed;
          flapF = 0.45 + 0.8 * s.flapNeed;
        } else {
          // Steer onto the spot while settling.
          const aim = s.goal ? clamp((tx - s.x) * 1.8, -140, 140) : Math.sign(s.vx) * 25;
          s.vx = ease(s.vx, aim, s.goal ? 2.4 : 1.6, dt);
          s.vy = ease(s.vy, altT > 0 ? -105 : 0, 2.4, dt);
          wFlare = 1;
          flapA = 0.6;
          flapF = 1.5;
          // Missed it (dropped past the top edge): settle for the floor.
          if (s.goal && altT < -30) s.goal = null;
        }
        wFly = 1;
        wArms = 1;
        climb = Math.sin(s.th) * (1 - s.wFlare);
        const onSpot = !s.goal || Math.abs(s.x - tx) < 45;
        if (altT <= 1.5 && s.vy <= 0 && onSpot) {
          s.y = ty;
          s.vy = 0;
          s.dip = 0.09;
          s.flaring = false;
          if (s.goal) {
            s.perch = s.goal;
            s.goal = null;
            s.vx = 0;
            emit("perch", `${s.perch.reason}:${describe(s.perch.el)}`);
            setMode("idle", calm ? rand(6, 12) : rand(2.5, 4));
          } else {
            s.perch = null;
            s.vx = clamp(s.vx, -110, 110);
            s.dir = s.vx >= 0 ? 1 : -1;
            setMode("walk", rand(1.2, 2));
          }
          emitWorld("dreamerLanded", { x: s.x, y: vh - s.y });
        }
      }

      // Integrate.
      s.x += s.vx * dt;
      s.y += s.vy * dt;
      if (s.y < GROUND) {
        s.y = GROUND;
        if (s.vy < 0) s.vy = 0;
      }
      if (s.mode === "idle" || s.mode === "walk") {
        s.vy = 0;
        const surf = surface();
        if (surf) {
          s.y = surf.y; // ride the perch as the page scrolls
          if (s.perch) s.x = clamp(s.x, surf.x1 - 10, surf.x2 + 10);
        }
      }
      s.x = clamp(s.x, 30, vw - 30);
      s.y = Math.min(s.y, vh - 60);

      // Smooth the blend weights so every transition eases.
      s.wFly = ease(s.wFly, wFly, 2.4, dt);
      s.wArms = ease(s.wArms, wArms, 3.2, dt);
      s.wFlare = ease(s.wFlare, wFlare, 3, dt);
      s.wHover = ease(s.wHover, wHover, 2.2, dt);
      s.wDash = ease(
        s.wDash,
        s.mode === "fly" && !s.man && !s.scoop ? clamp((s.v - 235) / 70, 0, 1) : 0,
        2.5,
        dt
      );
      // Outside cruise flight, the heading just follows the motion.
      if (s.mode !== "fly" && !(s.mode === "land" && !s.flaring)) {
        if (Math.hypot(s.vx, s.vy) > 20) s.th = Math.atan2(s.vy, s.vx);
        s.v = Math.hypot(s.vx, s.vy);
      }
      // Belly side flips (with a roll through the camera) once he's clearly
      // heading the other way -- never mid-loop.
      if (!s.man) {
        if (Math.cos(s.th) > 0.35) s.belly = 1;
        else if (Math.cos(s.th) < -0.35) s.belly = -1;
      }
      const bank = clamp(s.om * 0.16, -0.3, 0.3) * s.belly;
      const rollT =
        (s.belly > 0 ? ROLL_VIEW : Math.PI - ROLL_VIEW) +
        bank +
        0.05 * Math.sin(s.t * 1.3);
      s.roll = ease(s.roll, rollT, 3.2, dt);
      s.flapA = ease(s.flapA, flapA, 2.5, dt);
      s.flapF = ease(s.flapF, flapF, 2.5, dt);
      s.wTrail = ease(s.wTrail, s.mode === "fly" || s.mode === "land" ? 1 : 0, 1.5, dt);
      s.dip = ease(s.dip, 0, 5, dt);
      const holding = !!s.scoop && s.scoop.phase !== "approach";
      const reaching = !!s.scoop && s.scoop.phase === "approach";
      s.wCarry = ease(s.wCarry, holding ? 1 : reaching ? 0.55 : 0, 4, dt);

      const speed = Math.abs(s.vx);
      if (speed > 18) s.dir = s.vx > 0 ? 1 : -1;
      const run = clamp((speed - 80) / 90, 0, 1);
      const amp = clamp(speed / 45, 0, 1);
      s.phase += (dt * 2 * Math.PI * speed) / (PX * (1.3 + 0.7 * run));
      s.psi += dt * 2 * Math.PI * s.flapF;

      // Glance around when idle, sometimes straight at the viewer.
      s.lookTimer -= dt;
      if (s.lookTimer <= 0) {
        s.lookTimer = rand(1.4, 3.2);
        s.lookTarget =
          s.mode === "idle" && Math.random() < 0.35
            ? -s.yaw * 0.75
            : s.mode === "idle"
            ? rand(-0.5, 0.5)
            : 0;
      }
      s.look = ease(s.look, s.lookTarget, 3, dt);

      // Facing: three-quarter view toward travel, turning through the camera.
      const yawTarget =
        s.dir *
        (s.mode === "idle" ? 0.75 : 1.15 - 0.35 * Math.max(s.wFly, s.wArms));
      s.yaw = ease(s.yaw, yawTarget, 4, dt);

      // Pose.
      const P = groundPose({ phase: s.phase, amp, run, t: s.t, lookY: s.look });
      // + when curving toward his back (pulling up), - when tucking under.
      const turn = clamp((s.om * s.belly) / 2, -1, 1);
      mixInto(
        P,
        flyBody({ t: s.t, climb, turn, speed: s.v, hoverVx: s.vx * s.dir }),
        s.wFly
      );
      mixInto(P, flarePose(), s.wFlare);
      const wOrient = s.wFly * (1 - s.wHover) * (1 - s.wFlare);
      // Skewed stroke: quick powerful downbeat, slower recovery.
      const f = Math.sin(s.psi + 0.5 * Math.sin(s.psi));
      const upstroke = Math.max(0, Math.cos(s.psi));
      mixInto(
        P,
        flapArms({ f, A: s.flapA, p: wOrient, upstroke }),
        s.wArms
      );
      mixInto(P, dashArms(), s.wDash * s.wArms);
      mixInto(P, carryArms(), s.wCarry);
      P.hipsY -= s.dip;
      applyPose(rig, P);

      // Blink every few seconds (~150 ms), occasionally a double blink.
      s.blinkIn -= dt;
      if (s.blinkIn < -0.15)
        s.blinkIn = Math.random() < 0.15 ? 0.25 : rand(2.2, 5.5);
      rig.setBlink(s.blinkIn < 0 ? Math.sin((-s.blinkIn / 0.15) * Math.PI) : 0);

      // Orientation: upright (ground, hover, flare) slerped into the
      // path-aligned flight frame.
      _E.set(P.pitch, s.yaw, 0, "YXZ");
      qUp.setFromEuler(_E);
      flightQuat(s.th, s.roll, qFly);
      rig.yaw.rotation.set(0, 0, 0);
      rig.pitch.quaternion.copy(qUp).slerp(qFly, wOrient);
      const bob = Math.sin(s.psi) * 4 * s.flapA * s.wHover;
      rig.root.position.set(s.x, s.y + bob, 0);

      const floorY = s.perch && (s.mode === "idle" || s.mode === "walk") ? s.y : GROUND;
      const a = clamp((s.y - floorY) / 320, 0, 1);
      shadow.position.set(s.x, floorY + 1, -300);
      shadow.scale.set(26 * (1 - 0.55 * a), 4.5 * (1 - 0.55 * a), 1);
      shadow.material.opacity = 0.16 * (1 - 0.8 * a);

      publish();
      s.saveIn -= dt;
      if (s.saveIn <= 0) {
        s.saveIn = 1;
        save();
      }

      // Trails.
      rig.root.updateMatrixWorld(true);
      ["L", "R"].forEach((k, i) => {
        const tr = trails[i];
        rig.legs[k].ankle.getWorldPosition(handPos);
        const { pos, col } = tr;
        if (!tr.primed) {
          for (let j = 0; j < TRAIL_N; j += 1) {
            pos[j * 3] = handPos.x;
            pos[j * 3 + 1] = handPos.y;
            pos[j * 3 + 2] = -50;
          }
          tr.primed = true;
        }
        pos.copyWithin(0, 3);
        pos[(TRAIL_N - 1) * 3] = handPos.x;
        pos[(TRAIL_N - 1) * 3 + 1] = handPos.y;
        pos[(TRAIL_N - 1) * 3 + 2] = -50;
        for (let j = 0; j < TRAIL_N; j += 1)
          col[j * 4 + 3] =
            Math.pow(j / (TRAIL_N - 1), 1.8) *
            0.42 *
            s.wTrail *
            clamp(s.v / 260, 0.25, 1) *
            (1 - s.wHover * 0.7);
        tr.line.geometry.attributes.position.needsUpdate = true;
        tr.line.geometry.attributes.color.needsUpdate = true;
      });
    };

    const cpLocal = new THREE.Vector3();
    const headW = new THREE.Vector3();
    // Hands-together point in front of his chest (below it in flight), and
    // this frame's snapshot for Mochi. Runs after the pose and matrices update.
    const publish = () => {
      rig.root.updateMatrixWorld(true);
      cpLocal.set(0, 0.28, 0.3);
      rig.spine.localToWorld(cpLocal);
      s.cp.x = cpLocal.x;
      s.cp.y = vh - cpLocal.y;
      rig.neck.getWorldPosition(headW);
      const air = s.mode !== "idle" && s.mode !== "walk";
      companions.dreamer = {
        x: s.x,
        y: vh - s.y,
        headX: headW.x,
        headY: vh - headW.y,
        airborne: air,
        alt: s.y - GROUND,
        shadowX: s.x,
        carrying: !!s.scoop && s.scoop.phase !== "approach",
        at: performance.now(),
      };
      const c = companions.carry;
      if (c && s.scoop && (c.state === "held" || c.state === "requested")) {
        c.x = s.cp.x;
        c.y = s.cp.y;
        c.vx = s.vx;
        c.vy = -s.vy;
      }
    };

    // Mochi pounced near him: turn and look at her.
    const offPounce = onWorld("petPounce", ({ x }) => {
      if (s.mode !== "idle" && s.mode !== "walk") return;
      s.dir = x >= s.x ? 1 : -1;
      s.vx = 0;
      s.dip = Math.max(s.dip, 0.05);
      s.lookTarget = 0;
      s.lookTimer = 2.5;
      if (s.mode === "walk") setMode("idle", calm ? rand(4, 7) : rand(2, 3));
    });

    // Dev-only handle for stepping the sim by hand (headless tabs throttle rAF).
    if (process.env.NODE_ENV === "development")
      window.__dreamer = {
        s,
        rig,
        render: () => renderer.render(scene, camera),
        manual: false,
        run: (sec, fps = 60) => {
          for (let i = 0; i < sec * fps; i += 1) step(1 / fps);
          renderer.render(scene, camera);
          return { mode: s.mode, x: Math.round(s.x), y: Math.round(s.y) };
        },
      };

    let raf = 0;
    let last = performance.now();
    const loop = (now) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      if (ctl.current.paused) {
        raf = requestAnimationFrame(loop);
        return;
      }
      if (!(window.__dreamer && window.__dreamer.manual)) step(dt);
      renderer.render(scene, camera);
      raf = requestAnimationFrame(loop);
    };
    raf = requestAnimationFrame(loop);

    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("resize", onResize);
      window.removeEventListener("pagehide", save);
      save();
      if (director) director.destroy();
      offPounce();
      if (companions.carry && companions.carry.state === "held") {
        companions.carry.state = "released";
      }
      companions.dreamer = null;
      rig.dispose();
      shadow.geometry.dispose();
      shadow.material.dispose();
      trails.forEach((t) => {
        t.line.geometry.dispose();
        t.line.material.dispose();
      });
      renderer.dispose();
      if (renderer.domElement.parentNode === host) host.removeChild(renderer.domElement);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isLight]);

  return (
    <div
      ref={hostRef}
      aria-hidden="true"
      data-pet-ignore
      style={{
        position: "fixed",
        inset: 0,
        pointerEvents: "none",
        zIndex,
        opacity: paused ? 0 : 1,
        transition: "opacity 400ms ease",
      }}
    />
  );
});

export default Dreamer;
